<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'

const games = ref([]), error = ref(''), active = ref(null), showForm = ref(false), showSettings = ref(false), searchResults = ref([]), searching = ref(false), now = ref(Date.now()), scanStatus = ref({ status:'idle', next_run_at:null }), previewScreenshot = ref(''), settingsTab = ref('scan'), glossary = ref([]), glossaryQ = ref(''), glossaryCategory = ref(''), glossaryDraft = reactive({source_text:'',target_text:'',category:''}), glossaryEditing = ref(null), glossaryBatch = ref(''), allTags = ref([]), selectedTags = ref([]), showMoreTags = ref(false), showTransfer = ref(false), transferSubdir = ref(''), transferTask = ref(null)
const refreshing = reactive({}), refreshCooldowns = reactive({}), refreshErrors = reactive({})
const filters = reactive({ q: '', source_type: '', play_status: '', sort: 'updated' })
const blank = () => ({ title:'', alias:'', cover_url:'', screenshots:'', description:'', developer:'', publisher:'', release_date:null, rating:null, tags:'', series:'', source_type:'custom', source_id:'', resource_type:'none', resource_url:'', play_status:'favorite' })
const form = reactive(blank()), scrape = reactive({ q:'', source_type:'rawg' })
const systemSettings = reactive({scan_enable:true,scan_cron:'0 3 * * *',scan_throttle_ms:50,scan_root:'/vol/baidu',local_game_root:'/vol/games',download_dir:'/vol/download/game',rawg_api_key:'',auto_translate:false,translator_type:'none',tencent_secret_id:'',tencent_secret_key:'',tencent_region:'ap-guangzhou'})
const statuses = { favorite:'仅收藏', archived:'已归档', downloading:'下载中', completed:'已通关' }
const api = async (path, options={}) => { const r = await fetch(path, { headers:{'Content-Type':'application/json'}, ...options }); if (!r.ok) throw new Error((await r.json().catch(()=>({detail:r.statusText}))).detail); return r.status === 204 ? null : r.json() }
const cover = value => value || 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="400" height="560"><rect width="100%" height="100%" fill="#27303d"/><text x="50%" y="50%" fill="#94a3b8" text-anchor="middle" font-size="28">NO COVER</text></svg>')
const screenshots = computed(() => { try { const value=JSON.parse(form.screenshots || '[]'); return Array.isArray(value) ? value.filter(url=>typeof url==='string' && url) : [] } catch { return [] } })
const directoryPath = value => { const path=(value || '').replace(/\\/g,'/'); if (!path || /^https?:\/\//.test(path)) return path; const directory=/\/[^/]+\.[^/]+$/.test(path) ? path.slice(0,path.lastIndexOf('/')+1) : path; return directory.endsWith('/') ? directory : `${directory}/` }
const visibleTags = computed(() => showMoreTags.value ? allTags.value : allTags.value.slice(0,50))
async function load() { try { [games.value, scanStatus.value] = await Promise.all([api('/api/games?'+new URLSearchParams({...filters,tag:selectedTags.value.join(',')})), api('/api/scans/status')]); error.value='' } catch(e) { error.value=e.message } }
async function loadTags() { allTags.value=(await api('/api/games/all-tags')).filter(item=>item.count>0) }
function toggleTag(tag) { selectedTags.value=selectedTags.value.includes(tag) ? selectedTags.value.filter(item=>item!==tag) : [...selectedTags.value,tag]; load() }
function openNew() { Object.assign(form, blank()); active.value=null; searchResults.value=[]; showForm.value=true }
function openGame(game) { active.value=game; Object.assign(form, {...game, resource_url:directoryPath(game.resource_url)}); transferTask.value=null; showForm.value=true }
async function save() { try { const url=active.value?`/api/games/${active.value.id}`:'/api/games'; form.resource_url=directoryPath(form.resource_url); await api(url,{method:active.value?'PUT':'POST',body:JSON.stringify(form)}); showForm.value=false; await load() } catch(e) { error.value=e.message } }
async function removeGame() { if (active.value && confirm('确认删除此游戏？')) { await api(`/api/games/${active.value.id}`,{method:'DELETE'}); showForm.value=false; await load() } }
async function scrapeSearch() { searching.value=true; try { searchResults.value=await api(`/api/metadata/search?${new URLSearchParams(scrape)}`) } catch(e) { error.value=e.message } finally { searching.value=false } }
function choose(item) { Object.assign(form, {...blank(), ...item, resource_type:'none', play_status:'favorite'}); searchResults.value=[] }
function downloadToPc() { window.location.href=`/api/games/${active.value.id}/download-to-pc` }
async function startTransfer() { try { transferTask.value=await api(`/api/games/${active.value.id}/transfer-to-local`,{method:'POST',body:JSON.stringify({target_subdir:transferSubdir.value})}); showTransfer.value=false; pollTransfer() } catch(e) { error.value=e.message } }
async function pollTransfer() { if (!transferTask.value || !['pending','running'].includes(transferTask.value.status)) return; try { transferTask.value=await api(`/api/downloads/transfer/${transferTask.value.id}`); if (['pending','running'].includes(transferTask.value.status)) setTimeout(pollTransfer,2000) } catch(e) { error.value=e.message } }
async function uploadCover(event) { if (!active.value || !event.target.files[0]) return; const data=new FormData(); data.append('file',event.target.files[0]); const result=await fetch(`/api/games/${active.value.id}/cover`,{method:'POST',body:data}); if(!result.ok) error.value='封面上传失败'; else { Object.assign(form,await result.json()); await load() } }
const isRefreshCooling = game => (refreshCooldowns[game.id] || 0) > now.value
async function refreshMetadata(game) { if (refreshing[game.id] || isRefreshCooling(game)) return; refreshing[game.id]=true; delete refreshErrors[game.id]; try { await api(`/api/games/${game.id}/refresh-metadata`,{method:'POST'}); refreshCooldowns[game.id]=Date.now()+60000; await load(); setTimeout(load, 1000) } catch(e) { refreshErrors[game.id]=e.message; setTimeout(()=>delete refreshErrors[game.id],3000) } finally { refreshing[game.id]=false } }
const scanRunning = computed(() => ['pending','running'].includes(scanStatus.value.status))
const nextScanAt = computed(() => scanStatus.value.next_run_at ? new Date(scanStatus.value.next_run_at).toLocaleString() : '未计划')
async function triggerScan(full=false) { if (full && !confirm('确认重建全量索引？')) return; try { scanStatus.value=await api(`/api/scans/${full?'full':'incremental'}`,{method:'POST',body:full?JSON.stringify({confirm:true}):undefined}) } catch(e) { error.value=e.message } }
async function openSettings() { try { Object.assign(systemSettings,await api('/api/settings')); systemSettings.rawg_api_key='';systemSettings.tencent_secret_id='';systemSettings.tencent_secret_key=''; await loadGlossary(); showSettings.value=true } catch(e) { error.value=e.message } }
async function saveSettings() { try { await api('/api/settings',{method:'PUT',body:JSON.stringify(systemSettings)}); systemSettings.rawg_api_key='';systemSettings.tencent_secret_id='';systemSettings.tencent_secret_key=''; await load() } catch(e) { error.value=e.message } }
async function testSettings(kind) { try { alert((await api(`/api/settings/test-${kind}`,{method:'POST'})).ok?'连接成功':'连接失败') } catch(e) { error.value=e.message } }
async function loadGlossary() { glossary.value=await api('/api/glossary?'+new URLSearchParams({q:glossaryQ.value,category:glossaryCategory.value})) }
async function saveGlossary() { try { const path=glossaryEditing.value?`/api/glossary/${glossaryEditing.value}`:'/api/glossary'; await api(path,{method:glossaryEditing.value?'PUT':'POST',body:JSON.stringify(glossaryDraft)}); Object.assign(glossaryDraft,{source_text:'',target_text:'',category:''});glossaryEditing.value=null;await loadGlossary() } catch(e) { error.value=e.message } }
async function deleteGlossary(id) { if(confirm('确认删除术语？')) { await api(`/api/glossary/${id}`,{method:'DELETE'});await loadGlossary() } }
async function importGlossary() { try { await api('/api/glossary/batch',{method:'POST',body:glossaryBatch.value});glossaryBatch.value='';await loadGlossary() } catch(e) { error.value=e.message } }
let timer; onMounted(()=>{load();loadTags();timer=setInterval(()=>{now.value=Date.now();load()},3000)}); onUnmounted(()=>clearInterval(timer))
</script>

<template>
  <main class="mx-auto max-w-7xl p-4 md:p-8">
    <header class="mb-7 flex flex-col gap-4 md:flex-row md:items-center md:justify-between"><div><h1 class="text-3xl font-bold tracking-tight">GAME ARCHIVE</h1><p class="mt-1 text-sm text-slate-400">你的个人游戏归档库</p></div><div class="flex gap-2"><button class="btn-muted" @click="openSettings">设置</button><button class="btn" @click="openNew">+ 添加游戏</button></div></header>
    <p v-if="error" class="mb-4 rounded bg-red-950 p-3 text-red-200">{{ error }}</p>
    <section class="panel mb-6 grid gap-3 md:grid-cols-4"><input v-model="filters.q" @input="load" placeholder="搜索游戏名" /><select v-model="filters.source_type" @change="load"><option value="">所有类型</option><option value="rawg">PC / 主机游戏</option><option value="vndb">GAL / 视觉小说</option><option value="custom">自定义</option></select><select v-model="filters.play_status" @change="load"><option value="">所有状态</option><option v-for="(label,key) in statuses" :value="key">{{label}}</option></select><select v-model="filters.sort" @change="load"><option value="updated">最近更新</option><option value="created">最近添加</option><option value="rating">评分最高</option></select></section>
    <section v-if="allTags.length" class="mb-6 flex items-center gap-2"><div class="flex flex-1 gap-2 overflow-x-auto"><button v-for="item in visibleTags" :key="item.tag" class="shrink-0 max-w-40 truncate rounded-full px-3 py-1 text-xs" :class="selectedTags.includes(item.tag)?'bg-accent text-slate-950':'bg-slate-700 text-slate-200'" :title="item.tag" @click="toggleTag(item.tag)">{{item.tag}} <span class="opacity-70">{{item.count}}</span></button></div><button v-if="allTags.length>50" class="btn-muted shrink-0" @click="showMoreTags=!showMoreTags">{{showMoreTags?'收起':'更多'}}</button><button v-if="selectedTags.length" class="btn-muted shrink-0" @click="selectedTags=[];load()">清除筛选</button></section>
    <section v-if="games.length" class="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6"><article v-for="game in games" :key="game.id" class="group relative cursor-pointer overflow-hidden rounded-lg bg-panel shadow-lg" @click="openGame(game)"><button class="absolute right-2 top-2 z-10 flex h-8 w-8 items-center justify-center rounded-full bg-slate-950/80 p-0 text-slate-200 hover:bg-slate-700" :disabled="refreshing[game.id] || isRefreshCooling(game)" :title="isRefreshCooling(game) ? '元数据刷新冷却中' : '刷新元数据'" aria-label="刷新元数据" @click.stop="refreshMetadata(game)"><svg class="h-4 w-4" :class="{'animate-spin': refreshing[game.id]}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20 11a8.1 8.1 0 0 0-15.5-2M4 5v4h4M4 13a8.1 8.1 0 0 0 15.5 2M20 19v-4h-4"/></svg></button><p v-if="refreshErrors[game.id]" class="absolute left-2 right-2 top-11 z-10 rounded bg-red-950/90 px-2 py-1 text-xs text-red-200">{{refreshErrors[game.id]}}</p><img :src="cover(game.cover_url)" class="aspect-[2/3] w-full object-cover transition duration-300 group-hover:scale-105" /><div class="p-3"><h2 class="truncate font-semibold">{{game.title}}</h2><div class="mt-2 flex justify-between text-xs text-slate-400"><span>{{ game.rating ? game.rating.toFixed(1) : '—' }}</span><span class="truncate pl-2">{{game.tags || statuses[game.play_status]}}</span></div></div></article></section>
    <p v-else class="py-20 text-center text-slate-500">还没有游戏，点击右上角开始归档。</p>

    <section class="panel mt-6"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-semibold">扫描配置</h2><p class="mt-1 text-sm text-slate-400">下次增量扫描：{{nextScanAt}}</p><p v-if="scanRunning" class="mt-1 text-sm text-accent">扫描中：{{scanStatus.message}}</p></div><div class="flex gap-2"><button class="btn-muted" :disabled="scanRunning" @click="triggerScan()">{{scanRunning?'扫描中':'立即增量扫描'}}</button><button class="btn" :disabled="scanRunning" @click="triggerScan(true)">重建全量索引</button></div></div></section>

    <div v-if="showForm" class="fixed inset-0 z-10 overflow-y-auto bg-black/70 p-4"><section class="mx-auto my-4 max-w-4xl rounded-xl bg-panel p-5 md:my-10"><div class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">{{active ? active.title : '添加游戏'}}</h2><button class="btn-muted" @click="showForm=false">关闭</button></div>
      <div v-if="!active" class="mb-6 rounded-lg bg-slate-800 p-4"><h3 class="mb-3 font-semibold">自动刮削元数据</h3><div class="flex gap-2"><input v-model="scrape.q" @keyup.enter="scrapeSearch" placeholder="输入游戏名"/><select v-model="scrape.source_type" class="max-w-32"><option value="rawg">RAWG</option><option value="vndb">VNDB</option></select><button class="btn" :disabled="searching" @click="scrapeSearch">{{searching?'搜索中':'搜索'}}</button></div><div v-if="searchResults.length" class="mt-3 max-h-60 overflow-auto"><button v-for="item in searchResults" :key="item.source_id" class="block w-full border-b border-slate-700 text-left hover:bg-slate-700" @click="choose(item)">{{item.title}} <span class="text-slate-400">{{item.release_date || ''}}</span></button></div></div>
      <form class="grid gap-3 md:grid-cols-2" @submit.prevent="save"><label v-if="active">数据源<input :value="form.source_type.toUpperCase()" readonly></label><label>游戏名<input v-model="form.title" required></label><label>别名<input v-model="form.alias"></label><label>开发商<input v-model="form.developer"></label><label>发行商<input v-model="form.publisher"></label><label>发售日期<input v-model="form.release_date" type="date"></label><label>评分（0-100）<input v-model.number="form.rating" type="number" min="0" max="100" step="0.1"></label><label>标签（逗号分隔）<input v-model="form.tags"></label><label>系列<input v-model="form.series"></label><label>资源类型<select v-model="form.resource_type"><option value="none">无</option><option value="nas_cloud">NAS挂载云盘</option><option value="nas_local">NAS本地游戏</option><option value="web_link">网盘链接</option></select></label><label>资源链接 / 路径<input v-model="form.resource_url" :placeholder="form.resource_type === 'web_link' ? 'https://...' : form.resource_type === 'nas_local' ? '/vol/games/游戏名/' : '/vol/baidu/游戏名/'"></label><label>游玩状态<select v-model="form.play_status"><option v-for="(label,key) in statuses" :value="key">{{label}}</option></select></label><label class="md:col-span-2">封面 URL<div class="flex gap-2"><input v-model="form.cover_url"><button class="btn shrink-0" type="button" @click="save">应用封面</button></div></label><label class="md:col-span-2">简介<textarea v-model="form.description" rows="4"></textarea></label><div class="flex gap-2 md:col-span-2"><button class="btn" type="submit">保存</button><button v-if="active" class="bg-red-700" type="button" @click="removeGame">删除</button></div></form>
      <section v-if="active" class="mt-7 border-t border-slate-700 pt-5"><h3 class="mb-3 font-semibold">自定义封面</h3><input type="file" accept="image/*" @change="uploadCover"><div v-if="screenshots.length" class="mt-5"><h3 class="mb-3 font-semibold">游戏截图</h3><div class="flex gap-3 overflow-x-auto pb-2"><button v-for="url in screenshots" :key="url" class="shrink-0 p-0" @click="previewScreenshot=url"><img :src="url" class="h-auto w-60 rounded object-cover" alt="游戏截图"></button></div></div><div v-if="form.resource_type !== 'none' && form.resource_url" class="mt-5"><a class="btn inline-block" :href="`/api/games/${active.id}/resource`" target="_blank">打开资源</a><p v-if="form.resource_type === 'web_link'" class="mt-3 text-sm text-slate-500">网盘链接不支持下载，请点击打开链接</p><div v-else class="mt-3 flex flex-wrap gap-2"><button class="btn" @click="downloadToPc">下载到本机</button><button v-if="form.resource_type === 'nas_cloud'" class="btn-muted" :disabled="transferTask && ['pending','running'].includes(transferTask.status)" @click="transferSubdir=form.title;showTransfer=true">转存到NAS本地</button></div><div v-if="transferTask" class="mt-3 rounded bg-slate-800 p-3 text-sm"><p>{{transferTask.message}}</p><div v-if="['pending','running'].includes(transferTask.status)" class="mt-2 h-1 overflow-hidden rounded bg-slate-700"><div class="h-full bg-accent" :style="{width: transferTask.total_files ? (transferTask.copied_files/transferTask.total_files*100)+'%' : '0%'}"></div></div><p v-if="transferTask.total_files" class="mt-1">{{transferTask.copied_files}} / {{transferTask.total_files}} 个文件</p><p v-if="transferTask.status==='completed'">{{transferTask.target_path}}</p></div></div></section>
    </section></div>
    <div v-if="showSettings" class="fixed inset-0 z-10 overflow-y-auto bg-black/70 p-4"><section class="mx-auto my-4 max-w-4xl rounded-xl bg-panel p-5 md:my-10"><div class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">系统设置</h2><button class="btn-muted" @click="showSettings=false">关闭</button></div><div class="mb-5 flex gap-2 overflow-x-auto"><button v-for="tab in [['scan','扫描设置'],['source','数据源'],['glossary','翻译术语表'],['about','关于']]" :class="settingsTab===tab[0]?'btn':'btn-muted'" @click="settingsTab=tab[0]">{{tab[1]}}</button></div><section v-if="settingsTab==='scan'" class="grid gap-3 md:grid-cols-2"><label class="flex items-center gap-2">定时同步<input v-model="systemSettings.scan_enable" type="checkbox" class="w-auto"></label><label>同步间隔<select v-model="systemSettings.scan_cron"><option value="0 3 * * *">每天凌晨3点</option><option value="0 */6 * * *">每6小时</option><option value="0 */12 * * *">每12小时</option><option value="0 * * * *">每小时</option><option :value="systemSettings.scan_cron">自定义 cron</option></select></label><label>云盘扫描根路径<input v-model="systemSettings.scan_root" placeholder="/vol/baidu/"></label><label>本地游戏扫描根路径<input v-model="systemSettings.local_game_root" placeholder="/vol/games/"></label><label>云盘转存默认下载路径<input v-model="systemSettings.download_dir" placeholder="/vol/download/game/"></label><p class="text-sm text-slate-400">下次扫描：{{nextScanAt}}</p><div class="flex gap-2 md:col-span-2"><button class="btn-muted" :disabled="scanRunning" @click="triggerScan()">立即增量扫描</button><button class="btn" :disabled="scanRunning" @click="triggerScan(true)">全量扫描</button></div></section><section v-else-if="settingsTab==='source'" class="grid gap-3 md:grid-cols-2"><label>RAWG API Key<input v-model="systemSettings.rawg_api_key" type="password" placeholder="已配置则留空"></label><button class="btn-muted self-end" @click="testSettings('rawg')">测试连接</button><label>翻译 API<select v-model="systemSettings.translator_type"><option value="none">关闭</option><option value="tencent">腾讯翻译君</option></select></label><label class="flex items-center gap-2 self-end">自动翻译<input v-model="systemSettings.auto_translate" type="checkbox" class="w-auto"></label><template v-if="systemSettings.translator_type==='tencent'"><label>SecretId<input v-model="systemSettings.tencent_secret_id" type="password" placeholder="已配置则留空"></label><label>SecretKey<input v-model="systemSettings.tencent_secret_key" type="password" placeholder="已配置则留空"></label><label>Region<input v-model="systemSettings.tencent_region" placeholder="ap-guangzhou"></label><button class="btn-muted self-end" @click="testSettings('translator')">测试翻译</button></template></section><section v-else-if="settingsTab==='glossary'"><div class="mb-3 flex gap-2"><input v-model="glossaryQ" placeholder="搜索原文" @input="loadGlossary"><input v-model="glossaryCategory" placeholder="分类" @input="loadGlossary"></div><div class="mb-3 grid gap-2 md:grid-cols-4"><input v-model="glossaryDraft.source_text" placeholder="原文"><input v-model="glossaryDraft.target_text" placeholder="译文"><input v-model="glossaryDraft.category" placeholder="分类"><button class="btn" @click="saveGlossary">{{glossaryEditing?'保存':'新增'}}</button></div><div v-for="item in glossary" :key="item.id" class="flex items-center gap-2 border-b border-slate-700 py-2 text-sm"><span class="flex-1">{{item.source_text}}</span><span class="flex-1">{{item.target_text}}</span><span>{{item.category}}</span><button class="btn-muted" @click="Object.assign(glossaryDraft,item);glossaryEditing=item.id">编辑</button><button class="bg-red-700" @click="deleteGlossary(item.id)">删除</button></div><textarea v-model="glossaryBatch" class="mt-4" rows="4" placeholder='批量导入 JSON：[{"source_text":"Action","target_text":"动作","category":"tag"}]'></textarea><button class="btn mt-2" @click="importGlossary">批量导入</button></section><section v-else class="space-y-2 text-sm text-slate-300"><p>版本：1.0.0</p><p>技术栈：FastAPI · SQLAlchemy Async · SQLite · Vue 3</p><p>数据目录：/app/data/</p></section><div class="mt-5"><button class="btn" @click="saveSettings">保存设置</button></div></section></div>
    <div v-if="showTransfer" class="fixed inset-0 z-20 flex items-center justify-center bg-black/70 p-4"><section class="w-full max-w-md rounded-xl bg-panel p-5"><h3 class="font-semibold">转存到 NAS 本地</h3><label class="mt-3 block">子目录名（可留空）<input v-model="transferSubdir" :placeholder="form.title"></label><div class="mt-4 flex justify-end gap-2"><button class="btn-muted" @click="showTransfer=false">取消</button><button class="btn" @click="startTransfer">确认转存</button></div></section></div>
    <div v-if="previewScreenshot" class="fixed inset-0 z-20 flex cursor-zoom-out items-center justify-center bg-black/90 p-4" @click="previewScreenshot=''"><img :src="previewScreenshot" class="max-h-full max-w-full object-contain" alt="游戏截图预览"></div>
  </main>
</template>